// Pixel art for the Office page: an isometric (2:1) office room and chibi
// workers. The art is original to this repo and generated by
// scripts/office-art/build-office-art.mjs (see docs/office-art.md).
//
// Composition contract:
// - Every sprite has an anchor (`FURNITURE_ANCHORS`): the sprite pixel that
//   sits on its floor reference point. For floor tiles that is the tile's top
//   corner; for walls the floor point at the segment's north corner; for the
//   station pieces the north corner of the desk's 2x1-tile footprint.
// - A desk station (desk, monitorOff/monitorOn, chair) and every character
//   frame share one frame size and origin (`STATION`): draw the desk, then a
//   monitor, then the character at the same top-left. Seated character frames
//   (sit, type1, type2, raiseHand) already include the chair; draw `chair` only
//   at an empty desk.
// - Characters are anchored at `STATION.seatX/seatY` (the chair's centre on
//   the floor). A resting character goes on a sofa seat (`SOFA_SEATS`).
// - The boss desk (`OFFICE_EXTRAS.bossDesk`) and the seated boss (`BOSS`)
//   share one frame: draw the desk, then the boss at the same top-left.
import charactersUrl from './characters.png';
import furnitureUrl from './furniture.png';
import {
  BOSS_LAYOUT,
  CHARACTER_LAYOUT,
  FURNITURE_LAYOUT,
  GENERIC_LOOK_ID,
  SOFA_SEAT_LAYOUT,
  STATION_LAYOUT,
  TILE_LAYOUT,
} from './layout.generated';

export interface SpriteRef {
  src: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

export const CHARACTER_POSES = ['sit', 'type1', 'type2', 'raiseHand', 'rest1', 'rest2', 'walk1', 'walk2', 'standRaise'] as const;
export type CharacterPose = (typeof CHARACTER_POSES)[number];

export interface CharacterSheet {
  id: string;
  frames: Record<CharacterPose, SpriteRef>;
}

export type FurnitureKey =
  | 'floor'
  | 'wall'
  | 'window'
  | 'desk'
  | 'monitorOff'
  | 'monitorOn'
  | 'chair'
  | 'plant'
  | 'sofa'
  | 'shelf';

/** Room pieces beyond the required set: the left wall, a carpet tile, lounge props, the boss desk. */
export type OfficeExtraKey = 'wallLeft' | 'windowLeft' | 'carpet' | 'rug' | 'coffeeTable' | 'bossDesk';

/** Isometric floor tile size in px (2:1). */
export const OFFICE_TILE: { w: number; h: number } = { w: TILE_LAYOUT.w, h: TILE_LAYOUT.h };

type FurnitureLayoutKey = keyof typeof FURNITURE_LAYOUT;

function furnitureRef(key: FurnitureLayoutKey): SpriteRef {
  const { x, y, w, h } = FURNITURE_LAYOUT[key];
  return { src: furnitureUrl, x, y, w, h };
}

export const FURNITURE: Record<FurnitureKey, SpriteRef> = {
  floor: furnitureRef('floor'),
  wall: furnitureRef('wall'),
  window: furnitureRef('window'),
  desk: furnitureRef('desk'),
  monitorOff: furnitureRef('monitorOff'),
  monitorOn: furnitureRef('monitorOn'),
  chair: furnitureRef('chair'),
  plant: furnitureRef('plant'),
  sofa: furnitureRef('sofa'),
  shelf: furnitureRef('shelf'),
};

export const OFFICE_EXTRAS: Record<OfficeExtraKey, SpriteRef> = {
  wallLeft: furnitureRef('wallLeft'),
  windowLeft: furnitureRef('windowLeft'),
  carpet: furnitureRef('carpet'),
  rug: furnitureRef('rug'),
  coffeeTable: furnitureRef('coffeeTable'),
  bossDesk: furnitureRef('bossDesk'),
};

/** Per sprite: the pixel (in the sprite) that sits on its floor reference point. */
export const FURNITURE_ANCHORS: Record<FurnitureKey | OfficeExtraKey, { x: number; y: number }> =
  Object.fromEntries(
    (Object.keys(FURNITURE_LAYOUT) as FurnitureLayoutKey[]).map((k) => [
      k,
      { x: FURNITURE_LAYOUT[k].anchorX, y: FURNITURE_LAYOUT[k].anchorY },
    ]),
  ) as Record<FurnitureKey | OfficeExtraKey, { x: number; y: number }>;

/**
 * The shared station frame. `deskX/deskY`: frame pixel on the north corner of
 * the desk footprint (2 tiles along the room's right wall, 1 deep; the chair
 * takes the tile in front). `seatX/seatY`: the character anchor.
 */
export const STATION: { w: number; h: number; deskX: number; deskY: number; seatX: number; seatY: number } = {
  ...STATION_LAYOUT,
};

/** Sofa-sprite pixels where a resting character's anchor (`STATION.seatX/seatY`) goes. */
export const SOFA_SEATS: ReadonlyArray<{ x: number; y: number }> = SOFA_SEAT_LAYOUT;

type LookId = keyof typeof CHARACTER_LAYOUT;

function sheetFor(id: LookId): CharacterSheet {
  const layout = CHARACTER_LAYOUT[id];
  const frames = Object.fromEntries(
    CHARACTER_POSES.map((pose) => {
      const { x, y, w, h } = layout[pose];
      return [pose, { src: charactersUrl, x, y, w, h }];
    }),
  ) as Record<CharacterPose, SpriteRef>;
  return { id, frames };
}

const LOOK_IDS = Object.keys(CHARACTER_LAYOUT) as LookId[];

/** The distinct looks for Claude Code / Codex employees (pick one stably per session). */
export const CHARACTERS: CharacterSheet[] = LOOK_IDS.filter((id) => id !== GENERIC_LOOK_ID).map(sheetFor);

/** The look for agents that are neither Claude Code nor Codex (hood up). */
export const GENERIC_CHARACTER: CharacterSheet = sheetFor(GENERIC_LOOK_ID);

/**
 * The boss, seated in a high-backed chair behind the boss desk (pixels the
 * desk covers are already cleared). Shares the bossDesk sprite's frame:
 * `deskX/deskY` is the north corner of the desk's footprint (the desk's
 * anchor), `seatX/seatY` the boss chair's centre on the floor.
 */
export const BOSS: SpriteRef & { deskX: number; deskY: number; seatX: number; seatY: number } = {
  src: charactersUrl,
  ...BOSS_LAYOUT,
};
